//! Round 37 regressions found by differential probing against `php 8.5.12`
//! (`/opt/homebrew/bin/php`, `php -r`, `LC_ALL=C TZ=UTC`). Expected strings are
//! the reference's recorded stdout, generated by running each snippet through
//! it; no PHP is needed to run them.

use phplang::eval_capture;

fn run(src: &str) -> String {
    eval_capture(src).unwrap_or_else(|e| panic!("eval error for {src:?}: {e}"))
}

#[test]
fn concat_assign_reads_the_variable_after_the_right_hand_side() {
    let src = r##"<?php $w = "a"; $w .= ($w = "x"); var_dump($w); function e() { echo "[e]"; return "E"; } $nv .= e(); echo "\n"; var_dump($nv); function f() { $q = "a"; $q .= ($q = "b"); return $q; } var_dump(f());"##;
    assert_eq!(
        run(src),
        r##"string(2) "xx"
[e]
Warning: Undefined variable $nv in Command line code on line 1

string(1) "E"
string(2) "bb"
"##
    );
}

#[test]
fn concat_assign_in_place_keeps_value_semantics() {
    let src = r##"<?php $s = "ab"; $a = $s; $s .= "c"; $arr = ["x"]; $v = $arr[0]; $v .= "y"; $r1 = "m"; $r2 = &$r1; $r2 .= "n"; function loc() { $q = "1"; $copy = $q; $q .= "2"; return "$copy/$q"; } function st() { static $c = ""; $c .= "s"; return $c; } st(); $c = "\xC3"; $c .= "\xA9"; echo $a, " ", $s, " ", $arr[0], $v, " ", $r1, " ", loc(), " ", st(), " ", var_export($c === "é", true), "\n"; $n = 5; $n .= 6; var_dump($n); class B { function __toString(): string { throw new Exception("boom"); } } $bb = "keep"; try { $bb .= new B; } catch (Exception $e) { echo $e->getMessage(), " "; } var_dump($bb);"##;
    assert_eq!(
        run(src),
        r##"ab abc xxy mn 1/12 ss true
string(2) "56"
boom string(4) "keep"
"##
    );
}

#[test]
fn foreach_over_an_object_keeps_numeric_string_names() {
    let src = r##"<?php $o = new stdClass; $o->{"5"} = 1; $o->{"x"} = 2; $o->{"-3"} = 3; $o->{"07"} = 4; foreach ($o as $k => $v) { var_dump($k); } class C { public $a = 1; private $p = 2; function walk() { foreach ($this as $k => $v) { echo var_export($k, true), "=", $v, " "; } echo "\n"; } } $c = new C; $c->walk(); foreach ((array) $o as $k => $v) { var_dump($k); }"##;
    assert_eq!(
        run(src),
        r##"string(1) "5"
string(1) "x"
string(2) "-3"
string(2) "07"
'a'=1 'p'=2 
int(5)
string(1) "x"
int(-3)
string(2) "07"
"##
    );
}

#[test]
fn foreach_by_reference_over_an_object_writes_its_properties() {
    let src = r##"<?php $o = new stdClass; $o->{"5"} = 1; $o->b = 2; foreach ($o as $k => &$v) { $v *= 10; echo var_export($k, true), " "; } unset($v); echo $o->{"5"}, " ", $o->b, "\n"; $a = [1, 2]; foreach ($a as &$w) { $w++; } unset($w); echo implode(",", $a), "\n";"##;
    assert_eq!(
        run(src),
        r##"'5' 'b' 10 20
2,3
"##
    );
}

#[test]
fn reflection_reports_where_a_declaration_was_written() {
    let src = r##"<?php #[Attr]
abstract
class A
extends stdClass
{
    #[X]
    public
    static
    function
    m()
    {}
    abstract
    protected function n();
}
#[Y]
function
f
()
{
}
$c = static
function
() {};
$d = fn
() => 1;
interface I {
}
enum E: int { case A = 1;
}
trait T { function t() {} }
$anon = new class {
    function z() {}
};
foreach (["A", "I", "E", "T", get_class($anon), "stdClass", "ArrayObject"] as $n) { $r = new ReflectionClass($n); echo var_export($r->getFileName(), true), " ", var_export($r->getStartLine(), true), "-", var_export($r->getEndLine(), true), "\n"; }
foreach ([new ReflectionMethod("A", "m"), new ReflectionMethod("A", "n"), new ReflectionFunction("f"), new ReflectionFunction($c), new ReflectionFunction($d), new ReflectionMethod("T", "t"), new ReflectionMethod($anon, "z"), new ReflectionFunction("strlen"), new ReflectionMethod("ArrayObject", "count")] as $r) { echo var_export($r->getFileName(), true), " ", var_export($r->getStartLine(), true), "-", var_export($r->getEndLine(), true), "\n"; }"##;
    assert_eq!(
        run(src),
        r##"'Command line code' 3-14
'Command line code' 26-27
'Command line code' 28-29
'Command line code' 30-30
'Command line code' 31-33
false false-false
false false-false
'Command line code' 9-11
'Command line code' 13-13
'Command line code' 16-20
'Command line code' 22-23
'Command line code' 24-25
'Command line code' 30-30
'Command line code' 32-32
false false-false
false false-false
"##
    );
}
